   1→/**
   2→ * Standalone WebSocket relay server for the thos dashboard.
   3→ *
   4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
   5→ * `dev` script). It cannot be a Next.js API route because API routes don't
   6→ * support persistent WebSocket connections.
   7→ *
   8→ * ## Architecture
   9→ *
  10→ * Two WebSocket path families:
  11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
  12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
  13→ *
  14→ * The server supports multiple concurrent agents, each tracked in the
  15→ * `agents` Map keyed by a short random ID.
  16→ *
  17→ * ## Connection flow (browser)
  18→ *
  19→ * On browser connect, the server sends two small messages:
  20→ * 1. `agent_list`  — metadata for all agents (sidebar).
  21→ * 2. `task_list`   — all tasks.
  22→ *
  23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
  24→ * browser sends `{ type: "request_history", agentId }` when the user
  25→ * selects an agent, and the server responds with `message_history` for
  26→ * that single agent. This avoids sending megabytes of JSON on connect,
  27→ * which caused multi-minute loading times on mobile networks.
  28→ *
  29→ * Live messages for active agents are still broadcast to all browsers
  30→ * via `relay` messages in real time.
  31→ *
  32→ * ## Message flow (spawning)
  33→ *
  34→ * 1. Browser sends `{ type: "spawn", prompt }`.
  35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
  36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
  37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
  38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
  39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
  40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
  41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
  42→ *
  43→ * ## Resilience features
  44→ *
  45→ * - **Server-side message history** — every relay message is stored per-agent.
  46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
  47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
  48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
  49→ *   can reconnect to the new server if they retry their WebSocket connection.
  50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
  51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
  52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
  53→ */
  54→import { WebSocketServer, WebSocket } from "ws";
  55→import { execSync, spawn } from "child_process";
  56→import { randomBytes } from "crypto";
  57→import type { IncomingMessage } from "http";
  58→import { readdirSync, statSync, existsSync } from "fs";
  59→import { join, dirname, basename } from "path";
  60→import type {
  61→  BrowserMessage,
  62→  ClaudeMessage,
  63→  ServerMessage,
  64→  AgentStatus,
  65→  AgentInfo,
  66→  Task,
  67→  Workspace,
  68→  DirectoryEntry,
  69→} from "../lib/types";
  70→import { SessionStore, type PersistedAgent } from "./session-store";
  71→import { TaskStore } from "./task-store";
  72→import { WorkspaceStore } from "./workspace-store";
  73→
  74→const PORT = 9900;
  75→const TMUX_SESSION_PREFIX = "thos-agent";
  76→
  77→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
  78→function isAllowedIP(ip: string | undefined): boolean {
  79→  if (!ip) return false;
  80→  // Strip IPv6-mapped IPv4 prefix
  81→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
  82→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
  83→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
  84→  const parts = addr.split(".");
  85→  if (parts.length !== 4) return false;
  86→  const first = parseInt(parts[0], 10);
  87→  const second = parseInt(parts[1], 10);
  88→  return first === 100 && second >= 64 && second <= 127;
  89→}
  90→
  91→const wss = new WebSocketServer({
  92→  port: PORT,
  93→  verifyClient: (info: { req: { socket: { remoteAddress?: string } } }) => {
  94→    const ip = info.req.socket.remoteAddress;
  95→    const allowed = isAllowedIP(ip);
  96→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
  97→    return allowed;
  98→  },
  99→});
 100→const store = new SessionStore();
 101→
 102→// ── Multi-agent state ──────────────────────────────────────────────────────
 103→
 104→interface AgentState {
 105→  agentId: string;
 106→  claudeSocket: WebSocket | null;
 107→  tmuxSession: string | null;
 108→  pendingPrompt: string | null;
 109→  status: AgentStatus;
 110→  label: string;
 111→  createdAt: number;
 112→  /** Captured from system/init, used in subsequent user messages. */
 113→  sessionId: string | null;
 114→  /** Workspace this agent belongs to. */
 115→  workspaceId: string | null;
 116→  /** Model name from system/init or requested at spawn time. */
 117→  model: string | null;
 118→  /** Whether this agent is pinned to the top of the sidebar. */
 119→  pinned: boolean;
 120→  /** Whether this agent is in the icebox (parked for later). */
 121→  iceboxed: boolean;
 122→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 123→  pendingControlRequests: Map<string, Record<string, unknown>>;
 124→  /** All messages sent to the browser for this agent (source of truth). */
 125→  messageHistory: ServerMessage[];
 126→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 127→  pendingMessages: string[];
 128→}
 129→
 130→const agents = new Map<string, AgentState>();
 131→const taskStore = new TaskStore();
 132→const tasks = new Map<string, Task>();
 133→const workspaceStore = new WorkspaceStore();
 134→const workspaces = new Map<string, Workspace>();
 135→
 136→/** All active browser connections (supports multiple tabs). */
 137→const browserSockets = new Set<WebSocket>();
 138→
 139→/** Per-browser workspace scope (null = show all). */
 140→const browserWorkspaceScope = new Map<WebSocket, string | null>();
 141→
 142→/** Generate a short random agent ID. */
 143→function newAgentId(): string {
 144→  return randomBytes(4).toString("hex");
 145→}
 146→
 147→// ── tmux helpers ───────────────────────────────────────────────────────────
 148→
 149→/** Return the set of currently alive tmux session names matching the thos prefix. */
 150→function listAliveTmuxSessions(): Set<string> {
 151→  try {
 152→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
 153→      encoding: "utf-8",
 154→    }).trim();
 155→    if (!output) return new Set();
 156→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
 157→  } catch {
 158→    return new Set();
 159→  }
 160→}
 161→
 162→// ── Persistence helpers ────────────────────────────────────────────────────
 163→
 164→/** Build a PersistedAgent snapshot from live state. */
 165→function toPersistedAgent(agent: AgentState): PersistedAgent {
 166→  return {
 167→    id: agent.agentId,
 168→    state: {
 169→      agentId: agent.agentId,
 170→      status: agent.status,
 171→      tmuxSession: agent.tmuxSession,
 172→      label: agent.label,
 173→      createdAt: agent.createdAt,
 174→      sessionId: agent.sessionId,
 175→      workspaceId: agent.workspaceId,
 176→      model: agent.model,
 177→      pinned: agent.pinned || undefined,
 178→      iceboxed: agent.iceboxed || undefined,
 179→    },
 180→    messageHistory: agent.messageHistory,
 181→  };
 182→}
 183→
 184→/**
 185→ * Compact a message history by deduplicating cumulative snapshots.
 186→ * Keeps only the last version of each assistant/user message ID.
 187→ * Called on restore to shrink legacy bloated histories.
 188→ */
 189→function compactHistory(history: ServerMessage[]): ServerMessage[] {
 190→  // Build a map of msgId → last index
 191→  const lastIndex = new Map<string, number>();
 192→  for (let i = 0; i < history.length; i++) {
 193→    const id = getRelayMessageId(history[i]);
 194→    if (id) lastIndex.set(id, i);
 195→  }
 196→  // Keep only messages that are either non-deduplicable or the last occurrence
 197→  return history.filter((msg, i) => {
 198→    const id = getRelayMessageId(msg);
 199→    if (!id) return true; // non-relay or no message ID — always keep
 200→    return lastIndex.get(id) === i;
 201→  });
 202→}
 203→
 204→/** Persist agent state (debounced — use for streaming events). */
 205→function persistAgent(agent: AgentState) {
 206→  store.save(toPersistedAgent(agent));
 207→}
 208→
 209→/** Persist agent state immediately (use for critical state changes). */
 210→function persistAgentSync(agent: AgentState) {
 211→  store.saveSync(toPersistedAgent(agent));
 212→}
 213→
 214→// ── Restore from disk on startup ───────────────────────────────────────────
 215→
 216→function restoreAgents() {
 217→  const persisted = store.loadAll();
 218→  const aliveSessions = listAliveTmuxSessions();
 219→
 220→  for (const p of persisted) {
 221→    const agent: AgentState = {
 222→      agentId: p.state.agentId,
 223→      claudeSocket: null,
 224→      tmuxSession: p.state.tmuxSession,
 225→      pendingPrompt: null,
 226→      status: p.state.status,
 227→      label: p.state.label,
 228→      createdAt: p.state.createdAt,
 229→      sessionId: p.state.sessionId,
 230→      workspaceId: p.state.workspaceId ?? null,
 231→      model: p.state.model ?? null,
 232→      pinned: p.state.pinned ?? false,
 233→      iceboxed: p.state.iceboxed ?? false,
 234→      pendingControlRequests: new Map(),
 235→      messageHistory: compactHistory(p.messageHistory),
 236→      pendingMessages: [],
 237→    };
 238→
 239→    // Determine status for agents that were active when the server last ran
 240→    if (agent.status !== "done" && agent.status !== "error") {
 241→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
 242→      if (tmuxAlive) {
 243→        // tmux session still alive — CLI may reconnect to this server
 244→        agent.status = "disconnected";
 245→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
 246→      } else {
 247→        // tmux session gone — agent is archived
 248→        agent.status = "done";
 249→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
 250→      }
 251→    }
 252→
 253→    agents.set(agent.agentId, agent);
 254→    const originalCount = p.messageHistory.length;
 255→    const compactedCount = agent.messageHistory.length;
 256→    const saved = originalCount - compactedCount;
 257→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
 258→
 259→    // Persist compacted history back to disk
 260→    if (saved > 0) {
 261→      persistAgentSync(agent);
 262→    }
 263→  }
 264→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
 265→}
 266→
 267→restoreAgents();
 268→
 269→// ── Task restore + helpers ────────────────────────────────────────────────
 270→
 271→function restoreTasks() {
 272→  const persisted = taskStore.loadAll();
 273→  for (const t of persisted) {
 274→    tasks.set(t.id, t);
 275→  }
 276→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
 277→}
 278→
 279→restoreTasks();
 280→
 281→// ── Workspace restore + helpers ──────────────────────────────────────────
 282→
 283→function restoreWorkspaces() {
 284→  const persisted = workspaceStore.loadAll();
 285→  for (const w of persisted) {
 286→    workspaces.set(w.id, w);
 287→  }
 288→  console.log(`[restore] loaded ${persisted.length} workspaces from disk`);
 289→}
 290→
 291→restoreWorkspaces();
 292→
 293→/** Persist all workspaces to disk (sync). */
 294→function persistWorkspaces() {
 295→  workspaceStore.saveSync(Array.from(workspaces.values()));
 296→}
 297→
 298→/** Send the full workspace list to all browsers. */
 299→function broadcastWorkspaceList() {
 300→  const payload = JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) });
 301→  for (const ws of browserSockets) {
 302→    if (ws.readyState === WebSocket.OPEN) {
 303→      ws.send(payload);
 304→    }
 305→  }
 306→}
 307→
 308→/** Build the full task list sorted by creation time (newest first), optionally filtered by workspace. */
 309→function buildTaskList(workspaceId?: string | null): Task[] {
 310→  let list = Array.from(tasks.values());
 311→  if (workspaceId !== undefined && workspaceId !== null) {
 312→    list = list.filter((t) => t.workspaceId === workspaceId);
 313→  }
 314→  return list.sort((a, b) => b.createdAt - a.createdAt);
 315→}
 316→
 317→/** Send the full task list to all browsers (scoped per-browser workspace). */
 318→function broadcastTaskList() {
 319→  for (const ws of browserSockets) {
 320→    if (ws.readyState !== WebSocket.OPEN) continue;
 321→    const scope = browserWorkspaceScope.get(ws) ?? null;
 322→    ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 323→  }
 324→}
 325→
 326→/** Persist all tasks to disk (sync). */
 327→function persistTasks() {
 328→  taskStore.saveSync(Array.from(tasks.values()));
 329→}
 330→
 331→// ── Helpers ────────────────────────────────────────────────────────────────
 332→
 333→/** Send a JSON message to all connected browsers. */
 334→function sendToBrowser(msg: ServerMessage) {
 335→  const payload = JSON.stringify(msg);
 336→  for (const ws of browserSockets) {
 337→    if (ws.readyState === WebSocket.OPEN) {
 338→      ws.send(payload);
 339→    }
 340→  }
 341→}
 342→
 343→/** Build a snapshot of all agents for the sidebar, optionally filtered by workspace. */
 344→function buildAgentList(workspaceId?: string | null): AgentInfo[] {
 345→  let list = Array.from(agents.values());
 346→  if (workspaceId !== undefined && workspaceId !== null) {
 347→    list = list.filter((a) => a.workspaceId === workspaceId);
 348→  }
 349→  return list.map((a) => ({
 350→    agentId: a.agentId,
 351→    status: a.status,
 352→    tmuxSession: a.tmuxSession,
 353→    label: a.label,
 354→    createdAt: a.createdAt,
 355→    workspaceId: a.workspaceId,
 356→    model: a.model,
 357→    pinned: a.pinned || undefined,
 358→    iceboxed: a.iceboxed || undefined,
 359→  }));
 360→}
 361→
 362→/** Send the full agent list to all browsers (scoped per-browser workspace). */
 363→function broadcastAgentList() {
 364→  for (const ws of browserSockets) {
 365→    if (ws.readyState !== WebSocket.OPEN) continue;
 366→    const scope = browserWorkspaceScope.get(ws) ?? null;
 367→    ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 368→  }
 369→}
 370→
 371→/** Update an agent's status, notify browsers, broadcast list, and persist. */
 372→function setAgentStatus(agentId: string, status: AgentStatus) {
 373→  const agent = agents.get(agentId);
 374→  if (!agent) return;
 375→  agent.status = status;
 376→  sendToBrowser({ type: "status", agentId, status });
 377→  broadcastAgentList();
 378→  persistAgentSync(agent);
 379→}
 380→
 381→/**
 382→ * Extract a stable dedup key from a relay message, if present.
 383→ *
 384→ * Claude NDJSON sends cumulative snapshots for two message types:
 385→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 386→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 387→ *
 388→ * Additionally, one-per-session messages are deduplicated by session_id:
 389→ * - `system/init` — keyed by `init:<session_id>`
 390→ * - `result` — keyed by `result:<session_id>`
 391→ *
 392→ * We deduplicate by replacing the previous snapshot in `messageHistory`
 393→ * instead of appending, reducing storage from O(n²) to O(n).
 394→ */
 395→function getRelayMessageId(msg: ServerMessage): string | null {
 396→  if (msg.type !== "relay") return null;
 397→  const inner = msg.message;
 398→  if (inner.type === "assistant") {
 399→    return (inner as { message?: { id?: string } }).message?.id ?? null;
 400→  }
 401→  if (inner.type === "user") {
 402→    return (inner as { uuid?: string }).uuid ?? null;
 403→  }
 404→  // Dedup system/init and result by session_id so they don't stack on reload
 405→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
 406→    const sid = (inner as { session_id?: string }).session_id;
 407→    return sid ? `init:${sid}` : null;
 408→  }
 409→  if (inner.type === "result") {
 410→    const sid = (inner as { session_id?: string }).session_id;
 411→    return sid ? `result:${sid}` : null;
 412→  }
 413→  return null;
 414→}
 415→
 416→/**
 417→ * Record a message in the agent's history and send to all browsers.
 418→ *
 419→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
 420→ * previous snapshot with the same message ID instead of appending. This keeps
 421→ * only the final version of each message, dramatically reducing file sizes
 422→ * (e.g. 38 MB → ~1 MB for a typical session).
 423→ */
 424→function recordAndSend(agentId: string, msg: ServerMessage) {
 425→  const agent = agents.get(agentId);
 426→  if (agent) {
 427→    const msgId = getRelayMessageId(msg);
 428→    if (msgId) {
 429→      // Replace previous snapshot with same message ID (search from end for speed)
 430→      let replaced = false;
 431→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
 432→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
 433→          agent.messageHistory[i] = msg;
 434→          replaced = true;
 435→          break;
 436→        }
 437→      }
 438→      if (!replaced) {
 439→        agent.messageHistory.push(msg);
 440→      }
 441→    } else {
 442→      agent.messageHistory.push(msg);
 443→    }
 444→    persistAgent(agent); // debounced — streaming messages come fast
 445→  }
 446→  sendToBrowser(msg);
 447→}
 448→
 449→// ── Agent lifecycle ────────────────────────────────────────────────────────
 450→
 451→/**
 452→ * Stop a running agent by killing its tmux session and closing the CLI socket.
 453→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
 454→ */
 455→function stopAgent(agentId: string) {
 456→  const agent = agents.get(agentId);
 457→  if (!agent) return;
 458→
 459→  if (agent.tmuxSession) {
 460→    try {
 461→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 462→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
 463→    } catch {
 464→      // Session may already be dead
 465→    }
 466→  }
 467→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 468→    agent.claudeSocket.close();
 469→  }
 470→  agent.claudeSocket = null;
 471→  setAgentStatus(agentId, "done");
 472→}
 473→
 474→/**
 475→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
 476→ */
 477→function deleteAgent(agentId: string) {
 478→  const agent = agents.get(agentId);
 479→  if (!agent) return;
 480→
 481→  if (agent.tmuxSession) {
 482→    try {
 483→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 484→    } catch {}
 485→  }
 486→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 487→    agent.claudeSocket.close();
 488→  }
 489→  agents.delete(agentId);
 490→  store.remove(agentId);
 491→  broadcastAgentList();
 492→}
 493→
 494→/**
 495→ * Spawn a new Claude CLI process inside a tmux session.
 496→ *
 497→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
 498→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
 499→ * If `workspaceId` is provided, the tmux session starts in that workspace's cwd.
 500→ */
 501→function spawnClaude(prompt: string, workspaceId?: string | null, model?: string | null): string {
 502→  const agentId = newAgentId();
 503→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
 504→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
 505→
 506→  const agent: AgentState = {
 507→    agentId,
 508→    claudeSocket: null,
 509→    tmuxSession: null,
 510→    pendingPrompt: prompt,
 511→    status: "spawning",
 512→    label,
 513→    createdAt: Date.now(),
 514→    sessionId: null,
 515→    workspaceId: workspaceId ?? null,
 516→    model: model ?? null,
 517→    pinned: false,
 518→    iceboxed: false,
 519→    pendingControlRequests: new Map(),
 520→    messageHistory: [],
 521→    pendingMessages: [],
 522→  };
 523→  agents.set(agentId, agent);
 524→
 525→  // Notify browsers
 526→  sendToBrowser({ type: "spawned", agentId });
 527→  broadcastAgentList();
 528→  persistAgentSync(agent);
 529→
 530→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
 531→  // tmux new-session runs detached (-d) so spawn() returns immediately.
 532→  const modelFlag = model ? ` --model ${model}` : "";
 533→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions${modelFlag} --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
 534→
 535→  // If the agent belongs to a workspace, start tmux in that workspace's cwd
 536→  const workspace = workspaceId ? workspaces.get(workspaceId) : null;
 537→  const tmuxArgs = ["new-session", "-d", "-s", sessionName];
 538→  if (workspace) {
 539→    tmuxArgs.push("-c", workspace.cwd);
 540→  }
 541→  tmuxArgs.push("bash", "-c", claudeCmd);
 542→
 543→  const tmux = spawn("tmux", tmuxArgs, {
 544→    stdio: "ignore",
 545→  });
 546→
 547→  tmux.on("error", (err) => {
 548→    console.error("[tmux spawn error]", err);
 549→    setAgentStatus(agentId, "error");
 550→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
 551→  });
 552→
 553→  tmux.on("exit", (code) => {
 554→    if (code !== 0) {
 555→      console.error(`[tmux] new-session exited with code ${code}`);
 556→      setAgentStatus(agentId, "error");
 557→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
 558→      return;
 559→    }
 560→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
 561→    agent.tmuxSession = sessionName;
 562→    broadcastAgentList();
 563→    persistAgentSync(agent);
 564→  });
 565→
 566→  return agentId;
 567→}
 568→
 569→// ── Message handlers ───────────────────────────────────────────────────────
 570→
 571→/**
 572→ * Process an incoming NDJSON message from a specific Claude CLI.
 573→ *
 574→ * Status flow matches the Companion protocol:
 575→ * - hook_response → send pending prompt → "thinking"
 576→ * - system/init   → "connected" + capture session_id
 577→ * - assistant      → "thinking"
 578→ * - result         → "connected" (CLI stays alive for multi-turn)
 579→ * - CLI disconnect → "done" (handled in connection close handler)
 580→ */
 581→function handleClaudeMessage(agentId: string, raw: string) {
 582→  const agent = agents.get(agentId);
 583→  if (!agent) return;
 584→
 585→  let msg: ClaudeMessage;
 586→  try {
 587→    msg = JSON.parse(raw);
 588→  } catch {
 589→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
 590→    return;
 591→  }
 592→
 593→  // Silently ignore keep_alive messages
 594→  if (msg.type === "keep_alive") return;
 595→
 596→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
 597→
 598→  // After hook_response, send the pending prompt
 599→  if (
 600→    msg.type === "system" &&
 601→    (msg as { subtype?: string }).subtype === "hook_response" &&
 602→    agent.pendingPrompt &&
 603→    agent.claudeSocket?.readyState === WebSocket.OPEN
 604→  ) {
 605→    const promptContent = agent.pendingPrompt;
 606→    const userMsg = JSON.stringify({
 607→      type: "user",
 608→      message: { role: "user", content: promptContent },
 609→      parent_tool_use_id: null,
 610→      session_id: agent.sessionId ?? "",
 611→    });
 612→    console.log(`[server → claude:${agentId}]`, userMsg);
 613→    agent.claudeSocket.send(userMsg + "\n");
 614→    agent.pendingPrompt = null;
 615→    setAgentStatus(agentId, "thinking");
 616→
 617→    // Record the initial user message so it appears in chat and persists across reloads
 618→    recordAndSend(agentId, {
 619→      type: "relay",
 620→      agentId,
 621→      message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
 622→    });
 623→  }
 624→
 625→  // Track status based on message type
 626→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 627→    // Capture session_id and model for subsequent user messages
 628→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
 629→    agent.model = (msg as { model?: string }).model ?? agent.model;
 630→    setAgentStatus(agentId, "connected");
 631→  } else if (msg.type === "assistant") {
 632→    setAgentStatus(agentId, "thinking");
 633→  } else if (msg.type === "result") {
 634→    // CLI stays alive after result — ready for the next turn.
 635→    // Status only goes to "done" when the CLI WebSocket actually closes.
 636→    setAgentStatus(agentId, "connected");
 637→  }
 638→
 639→  // Store control_request inputs for building proper responses later
 640→  if (msg.type === "control_request") {
 641→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
 642→    if (cr.request_id && cr.request?.input) {
 643→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
 644→    }
 645→  }
 646→
 647→  // Record in history and relay to browsers
 648→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
 649→}
 650→
 651→/**
 652→ * Process an incoming JSON message from the browser.
 653→ * - `spawn`: create a new agent (does NOT kill others).
 654→ * - `send_message`: forward a follow-up user message to the specified agent.
 655→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
 656→ * - `kill_agent`: stop the CLI and tmux session.
 657→ * - `delete_agent`: permanently remove an agent.
 658→ * - `rename_agent`: update an agent's label.
 659→ * - `clear_history`: wipe an agent's message history.
 660→ * - `request_history`: send message history for a single agent (lazy loading).
 661→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
 662→ */
 663→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
 664→  let msg: BrowserMessage;
 665→  try {
 666→    msg = JSON.parse(raw);
 667→  } catch {
 668→    console.error("[browser] invalid JSON:", raw);
 669→    return;
 670→  }
 671→
 672→  console.log("[browser →]", msg.type);
 673→
 674→  switch (msg.type) {
 675→    case "spawn": {
 676→      const scope = browserWorkspaceScope.get(senderWs) ?? msg.workspaceId ?? null;
 677→      spawnClaude(msg.prompt, scope, msg.model);
 678→      break;
 679→    }
 680→
 681→    case "send_message": {
 682→      const agent = agents.get(msg.agentId);
 683→      if (!agent) {
 684→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
 685→        break;
 686→      }
 687→
 688→      // Record the user message in history so it persists across reloads.
 689→      // Do NOT broadcast — the sending browser already has it optimistically,
 690→      // and other browsers will get it when they request_history.
 691→      agent.messageHistory.push({
 692→        type: "relay",
 693→        agentId: msg.agentId,
 694→        message: { type: "user", message: { role: "user", content: msg.content } },
 695→      } as ServerMessage);
 696→      persistAgent(agent);
 697→
 698→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 699→        const userMsg = JSON.stringify({
 700→          type: "user",
 701→          message: { role: "user", content: msg.content },
 702→          parent_tool_use_id: null,
 703→          session_id: agent.sessionId ?? "",
 704→        });
 705→        agent.claudeSocket.send(userMsg + "\n");
 706→        setAgentStatus(msg.agentId, "thinking");
 707→      } else {
 708→        // Queue message for delivery when CLI reconnects
 709→        const userMsg = JSON.stringify({
 710→          type: "user",
 711→          message: { role: "user", content: msg.content },
 712→          parent_tool_use_id: null,
 713→          session_id: agent.sessionId ?? "",
 714→        });
 715→        agent.pendingMessages.push(userMsg);
 716→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
 717→        persistAgentSync(agent);
 718→      }
 719→      break;
 720→    }
 721→
 722→    case "control_response": {
 723→      const agent = agents.get(msg.agentId);
 724→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
 725→        // Retrieve the original tool input to include as updatedInput (required by protocol)
 726→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
 727→        agent.pendingControlRequests.delete(msg.request_id);
 728→
 729→        // If the browser sent answers (from AskUserQuestion), merge them into the input
 730→        const answers = (msg as { answers?: Record<string, string> }).answers;
 731→        const updatedInput = answers
 732→          ? { ...originalInput, answers }
 733→          : originalInput;
 734→
 735→        const response = JSON.stringify({
 736→          type: "control_response",
 737→          response: {
 738→            subtype: "success",
 739→            request_id: msg.request_id,
 740→            response: msg.allow
 741→              ? { behavior: "allow", updatedInput }
 742→              : { behavior: "deny", message: "Denied by user" },
 743→          },
 744→        });
 745→        agent.claudeSocket.send(response + "\n");
 746→      }
 747→      break;
 748→    }
 749→
 750→    case "kill_agent":
 751→      stopAgent(msg.agentId);
 752→      break;
 753→
 754→    case "delete_agent":
 755→      deleteAgent(msg.agentId);
 756→      break;
 757→
 758→    case "rename_agent": {
 759→      const agent = agents.get(msg.agentId);
 760→      if (!agent) break;
 761→      agent.label = msg.label;
 762→      broadcastAgentList();
 763→      persistAgentSync(agent);
 764→      break;
 765→    }
 766→
 767→    case "clear_history": {
 768→      const agent = agents.get(msg.agentId);
 769→      if (!agent) break;
 770→      agent.messageHistory = [];
 771→      persistAgentSync(agent);
 772→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
 773→      break;
 774→    }
 775→
 776→    case "pin_agent": {
 777→      const agent = agents.get(msg.agentId);
 778→      if (!agent) break;
 779→      agent.pinned = msg.pinned;
 780→      broadcastAgentList();
 781→      persistAgentSync(agent);
 782→      break;
 783→    }
 784→
 785→    case "icebox_agent": {
 786→      const agent = agents.get(msg.agentId);
 787→      if (!agent) break;
 788→      agent.iceboxed = msg.iceboxed;
 789→      broadcastAgentList();
 790→      persistAgentSync(agent);
 791→      break;
 792→    }
 793→
 794→    case "move_agent": {
 795→      const agent = agents.get(msg.agentId);
 796→      if (!agent) break;
 797→      agent.workspaceId = msg.workspaceId;
 798→      broadcastAgentList();
 799→      persistAgentSync(agent);
 800→      break;
 801→    }
 802→
 803→    case "request_history": {
 804→      console.log(`[browser] request_history for ${msg.agentId}`);
 805→      sendHistoryToSocket(senderWs, msg.agentId);
 806→      break;
 807→    }
 808→
 809→    case "create_task": {
 810→      const taskId = randomBytes(4).toString("hex");
 811→      const task: Task = {
 812→        id: taskId,
 813→        title: msg.title,
 814→        description: msg.description,
 815→        status: "todo",
 816→        priority: msg.priority,
 817→        agentId: null,
 818→        workspaceId: browserWorkspaceScope.get(senderWs) ?? null,
 819→        createdAt: Date.now(),
 820→        updatedAt: Date.now(),
 821→      };
 822→      tasks.set(taskId, task);
 823→      persistTasks();
 824→      broadcastTaskList();
 825→      break;
 826→    }
 827→
 828→    case "update_task": {
 829→      const task = tasks.get(msg.taskId);
 830→      if (!task) break;
 831→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
 832→      persistTasks();
 833→      broadcastTaskList();
 834→
 835→      // Archive the linked agent when a task is marked as done
 836→      if (task.status === "done" && task.agentId) {
 837→        const linkedAgent = agents.get(task.agentId);
 838→        if (linkedAgent && linkedAgent.status !== "done") {
 839→          stopAgent(task.agentId);
 840→        }
 841→      }
 842→      break;
 843→    }
 844→
 845→    case "delete_task": {
 846→      tasks.delete(msg.taskId);
 847→      persistTasks();
 848→      broadcastTaskList();
 849→      break;
 850→    }
 851→
 852→    case "delegate_task": {
 853→      const task = tasks.get(msg.taskId);
 854→      if (!task) break;
 855→      const prompt = `Task: ${task.title}\n\n${task.description}`;
 856→      const agentId = spawnClaude(prompt, task.workspaceId);
 857→      task.agentId = agentId;
 858→      task.status = "in-progress";
 859→      task.updatedAt = Date.now();
 860→      persistTasks();
 861→      broadcastTaskList();
 862→      break;
 863→    }
 864→
 865→    // ── Workspace messages ──────────────────────────────────────────────
 866→
 867→    case "set_workspace": {
 868→      browserWorkspaceScope.set(senderWs, msg.workspaceId);
 869→      // Re-send scoped agent list and task list to this browser
 870→      const scope = msg.workspaceId;
 871→      senderWs.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 872→      senderWs.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 873→      break;
 874→    }
 875→
 876→    case "create_workspace": {
 877→      const id = randomBytes(4).toString("hex");
 878→      const workspace: Workspace = {
 879→        id,
 880→        name: msg.name,
 881→        cwd: msg.cwd,
 882→        createdAt: Date.now(),
 883→      };
 884→      workspaces.set(id, workspace);
 885→      persistWorkspaces();
 886→      broadcastWorkspaceList();
 887→      break;
 888→    }
 889→
 890→    case "rename_workspace": {
 891→      const workspace = workspaces.get(msg.workspaceId);
 892→      if (!workspace) break;
 893→      workspace.name = msg.name;
 894→      persistWorkspaces();
 895→      broadcastWorkspaceList();
 896→      break;
 897→    }
 898→
 899→    case "delete_workspace": {
 900→      workspaces.delete(msg.workspaceId);
 901→      // Unlink agents and tasks from the deleted workspace
 902→      for (const agent of agents.values()) {
 903→        if (agent.workspaceId === msg.workspaceId) {
 904→          agent.workspaceId = null;
 905→          persistAgentSync(agent);
 906→        }
 907→      }
 908→      for (const task of tasks.values()) {
 909→        if (task.workspaceId === msg.workspaceId) {
 910→          task.workspaceId = null;
 911→        }
 912→      }
 913→      persistTasks();
 914→      persistWorkspaces();
 915→      broadcastWorkspaceList();
 916→      broadcastAgentList();
 917→      broadcastTaskList();
 918→      break;
 919→    }
 920→
 921→    case "browse_directory": {
 922→      const dirPath = msg.path;
 923→      try {
 924→        if (!existsSync(dirPath)) {
 925→          senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 926→          break;
 927→        }
 928→        const entries: DirectoryEntry[] = [];
 929→        // Add parent directory entry
 930→        const parent = dirname(dirPath);
 931→        if (parent !== dirPath) {
 932→          entries.push({ name: "..", path: parent });
 933→        }
 934→        // List subdirectories only
 935→        const items = readdirSync(dirPath);
 936→        for (const item of items) {
 937→          if (item.startsWith(".")) continue; // skip dotfiles
 938→          const fullPath = join(dirPath, item);
 939→          try {
 940→            const stat = statSync(fullPath);
 941→            if (stat.isDirectory()) {
 942→              entries.push({ name: item, path: fullPath });
 943→            }
 944→          } catch {
 945→            // skip inaccessible entries
 946→          }
 947→        }
 948→        // Sort: ".." first, then alphabetical
 949→        entries.sort((a, b) => {
 950→          if (a.name === "..") return -1;
 951→          if (b.name === "..") return 1;
 952→          return a.name.localeCompare(b.name);
 953→        });
 954→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries }));
 955→      } catch (err) {
 956→        console.error(`[browse_directory] error reading ${dirPath}:`, err);
 957→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 958→      }
 959→      break;
 960→    }
 961→  }
 962→}
 963→
 964→// ── Send message history to a single browser socket ────────────────────────
 965→
 966→/** Send initial state (workspaces, agent list, tasks) to a newly connected browser. */
 967→function sendFullStateToSocket(ws: WebSocket) {
 968→  if (ws.readyState !== WebSocket.OPEN) return;
 969→
 970→  // Workspace list
 971→  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));
 972→
 973→  // Agent list (sidebar metadata) — scoped if browser has a workspace set
 974→  const scope = browserWorkspaceScope.get(ws) ?? null;
 975→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 976→
 977→  // Task list — scoped if browser has a workspace set
 978→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 979→}
 980→
 981→/** Send message history for a single agent to a specific browser socket. */
 982→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
 983→  const agent = agents.get(agentId);
 984→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
 985→  ws.send(
 986→    JSON.stringify({
 987→      type: "message_history",
 988→      agentId: agent.agentId,
 989→      messages: agent.messageHistory,
 990→    })
 991→  );
 992→}
 993→
 994→// ── Connection handler — route by URL path ────────────────────────────────
 995→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
 996→  const path = req.url ?? "/";
 997→  console.log(`[ws connected] path=${path}`);
 998→
 999→  if (path === "/browser") {
1000→    // Send full state BEFORE adding to browserSockets so that live
1001→    // relay broadcasts don't interleave with the history replay.
1002→    sendFullStateToSocket(ws);
1003→    browserSockets.add(ws);
1004→
1005→    ws.on("message", (data) => {
1006→      handleBrowserMessage(data.toString(), ws);
1007→    });
1008→
1009→    ws.on("close", () => {
1010→      console.log("[browser disconnected]");
1011→      browserSockets.delete(ws);
1012→      browserWorkspaceScope.delete(ws);
1013→      // Do NOT kill agents — keep them alive for reconnect
1014→    });
1015→  } else if (path.startsWith("/claude/")) {
1016→    // Parse agentId from /claude/<agentId>
1017→    const agentId = path.slice("/claude/".length);
1018→    const agent = agents.get(agentId);
1019→
1020→    if (!agent) {
1021→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
1022→      ws.close();
1023→      return;
1024→    }
1025→
1026→    agent.claudeSocket = ws;
1027→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
1028→
1029→    // Notify browsers that CLI is connected
1030→    sendToBrowser({ type: "cli_connected", agentId });
1031→
1032→    // Flush any pending messages queued while CLI was disconnected
1033→    if (agent.pendingMessages.length > 0) {
1034→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
1035→      for (const queued of agent.pendingMessages) {
1036→        ws.send(queued + "\n");
1037→      }
1038→      agent.pendingMessages = [];
1039→      persistAgentSync(agent);
1040→    }
1041→
1042→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
1043→    // server to send the first user message rather than emitting
1044→    // hook_started/hook_response on connect.
1045→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
1046→      const promptContent = agent.pendingPrompt;
1047→      const userMsg = JSON.stringify({
1048→        type: "user",
1049→        message: { role: "user", content: promptContent },
1050→        parent_tool_use_id: null,
1051→        session_id: agent.sessionId ?? "",
1052→      });
1053→      console.log(`[server → claude:${agentId}] sending pending prompt`);
1054→      ws.send(userMsg + "\n");
1055→      agent.pendingPrompt = null;
1056→      setAgentStatus(agentId, "thinking");
1057→
1058→      // Record the initial user message so it appears in chat and persists across reloads
1059→      recordAndSend(agentId, {
1060→        type: "relay",
1061→        agentId,
1062→        message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
1063→      });
1064→    }
1065→
1066→    ws.on("message", (data) => {
1067→      handleClaudeMessage(agentId, data.toString());
1068→    });
1069→
1070→    ws.on("close", () => {
1071→      console.log(`[claude:${agentId} CLI disconnected]`);
1072→      if (agent.claudeSocket === ws) {
1073→        agent.claudeSocket = null;
1074→        if (agent.status !== "error") {
1075→          setAgentStatus(agentId, "done");
1076→          sendToBrowser({ type: "cli_disconnected", agentId });
1077→
1078→          // Auto-complete any task linked to this agent
1079→          for (const task of tasks.values()) {
1080→            if (task.agentId === agentId && task.status !== "done") {
1081→              task.status = "done";
1082→              task.updatedAt = Date.now();
1083→              persistTasks();
1084→              broadcastTaskList();
1085→              break;
1086→            }
1087→          }
1088→        }
1089→      }
1090→    });
1091→  } else {
1092→    console.log(`[ws] unknown path: ${path}, closing`);
1093→    ws.close();
1094→  }
1095→});
1096→
1097→// ── Graceful shutdown ─────────────────────────────────────────────────────
1098→
1099→function shutdown() {
1100→  console.log("[ws server] shutting down...");
1101→
1102→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
1103→  // so CLI processes can reconnect if the server restarts.
1104→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
1105→  store.flushAll(allPersisted);
1106→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
1107→
1108→  taskStore.flush(Array.from(tasks.values()));
1109→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
1110→
1111→  persistWorkspaces();
1112→  console.log(`[ws server] saved ${workspaces.size} workspaces to disk`);
1113→
1114→  wss.close();
1115→  process.exit(0);
1116→}
1117→
1118→process.on("SIGTERM", shutdown);
1119→process.on("SIGINT", shutdown);
1120→
1121→console.log(`[ws server] listening on port ${PORT}`);
1122→

